// Assemble the §6.6 strategic_refresh prompt from the three fetched inputs.
// Canonical prompt body also lives in fb_messaging_prompts(name='strategic_refresh');
// swap this inline copy for a fetch of that row if you edit the prompt in the DB.
const bank = $('Get Message Bank').first()?.json?.variables ?? {};
const rej = $('Get Rejections').all().map(i => i.json);
const eng = $('Get Engagement').all().map(i => i.json);
const rejCounts = {};
for (const r of rej) { if (!r || !r.reason_code) continue; rejCounts[r.reason_code] = (rejCounts[r.reason_code] || 0) + 1; }
const rejection_summary = Object.entries(rejCounts).map(([k, v]) => k + ': ' + v).join(', ') || 'none';
function avgBy(key) { const m = {}; for (const e of eng) { if (e == null || e.engagement_rate == null) continue; (m[e[key]] = m[e[key]] || []).push(Number(e.engagement_rate)); } return Object.entries(m).map(([k, a]) => k + ': ' + (a.reduce((x, y) => x + y, 0) / a.length * 100).toFixed(1) + '%').join(', ') || 'no data'; }
const engagement_summary = 'by pillar — ' + avgBy('pillar') + '; by archetype — ' + avgBy('archetype');
const now = new Date();
const mo = now.getMonth();
const season = (mo >= 5 && mo <= 10) ? 'Atlantic hurricane season (Jun-Nov) — storm/insurance/security focus' : 'off-season (Dec-May) — comfort/energy/value focus and pre-season planning';
const season_context = now.toISOString().slice(0, 10) + '; ' + season;
const user = [
  "Act as Reece's strategic planning lead. Inputs:",
  '- current message bank: ' + JSON.stringify(bank),
  "- last quarter's rejection reasons (aggregated): " + rejection_summary,
  '- engagement by pillar and by archetype: ' + engagement_summary,
  '- season ahead: ' + season_context,
  'Do a brief SWOT + scenario pass for the next quarter of Florida impact-window content. Then propose: (a) specific message-bank edits, (b) which pillars to emphasize/de-emphasize and why, (c) prompt/style-guide tweaks that would reduce the most common rejection reasons. These are PROPOSALS for human approval.',
  'Return ONLY valid JSON:',
  '{"swot":{"strengths":[],"weaknesses":[],"opportunities":[],"threats":[]},"message_bank_edits":[],"pillar_emphasis":[],"prompt_tweaks":[]}'
].join('\n');
return [{ json: { user } }];

// Tolerant parse → the proposals object. Surfaced for human apply (no DB write).
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let obj; try { obj = JSON.parse(t); } catch (e) { const m = t.match(/\{[\s\S]*\}/); obj = m ? JSON.parse(m[0]) : {}; }
return [{ json: obj }];
